from __future__ import annotations

import copy
import hashlib
import json
import math
import random
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_INPUT = ROOT / "input" / "wheel_factory.json"
STAGES = ("cast", "cnc", "paint", "qc")
BTP_STAGES = STAGES[:-1]  # cast, cnc, paint: stages that hold semi-finished (BTP) stock


def save_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def load(path=DEFAULT_INPUT):
    data = upgrade_input(json.loads(Path(path).read_text(encoding="utf-8")))
    if data.get("schema_version") == 5:
        # Fixed runs per stage (dataset/wheel-factory-small/model_input.json):
        # a separate engine, see models/common/stage_runs/.
        from .stage_runs.instance import check
        return check(data)
    check_input(data)
    return data


def upgrade_input(data):
    """Explicit schema_version 3 -> 4 conversion; any other version passes through.

    v3 keyed cast/cnc/paint machines by FINAL product; v4 keys them by the BTP
    code that stage produces (see stage_item). The relabel goes through
    btp_routing. If two products route to one code but v3 gave them different
    rates/setups (e.g. a colour changeover at cast), the old data is ambiguous
    and is rejected rather than guessed. Returns a new dict; the input (e.g. a
    stored run snapshot) is never modified.
    """
    if data.get("schema_version") != 3:
        return data
    data = copy.deepcopy(data)
    routing = data.get("btp_routing", {})

    def put(target, key, value, where):
        if key in target and target[key] != value:
            raise ValueError(f"Cannot upgrade to schema_version 4: {where} maps two products "
                             f"onto '{key}' with different values ({target[key]} vs {value})")
        target[key] = value

    for mid, machine in data["machines"].items():
        stage = machine["stage"]
        if stage not in BTP_STAGES:
            continue
        item = lambda key: routing[key][stage] if key in routing else key  # noqa: E731
        rates = {}
        for p, v in machine["minutes_per_unit"].items():
            put(rates, item(p), v, f"{mid}.minutes_per_unit")
        matrix = {}
        for prev, row in machine["setup"].items():
            for p, v in row.items():
                put(matrix.setdefault(item(prev), {}), item(p), v, f"{mid}.setup[{item(prev)}]")
        machine["minutes_per_unit"], machine["setup"] = rates, matrix
        machine["initial_product"] = item(machine["initial_product"])
    data["schema_version"] = 4
    return data


def digest(data):
    return hashlib.sha256(json.dumps(data, sort_keys=True).encode()).hexdigest()


def stage_item(data, lot, stage):
    """Code a machine at `stage` actually works on (schema_version 4).

    cast/cnc/paint: the BTP code that stage PRODUCES for the lot's product
    (btp_routing), e.g. F_SILVER and F_BLACK both cast F_CAST. qc: the finished
    product itself. Machine speed, setup matrix and eligibility are keyed by this
    code, never by the final product, so colour-blind stages cannot carry
    colour-specific setups or eligibility.
    """
    if stage in BTP_STAGES:
        return data["btp_routing"][lot["product"]][stage]
    return lot["product"]


def duration(data, lot, machine):
    spec = data["machines"][machine]
    item = stage_item(data, lot, spec["stage"])
    return math.ceil(lot["quantity"] * spec["minutes_per_unit"][item] + spec["fixed_minutes"])


def setup(data, machine, previous, item):
    """`previous`/`item` are stage items (see stage_item) or a declared machine state."""
    return data["machines"][machine]["setup"][previous][item]


def eligible(data, lot, stage):
    item = stage_item(data, lot, stage)
    return [m for m, spec in data["machines"].items()
            if spec["stage"] == stage and item in spec["minutes_per_unit"]]


def technical_surplus(data):
    """Per product: units mandatory lots make beyond their order allocations (A02)."""
    allocated = {}
    for order in data["orders"]:
        for lid, qty in order["lot_allocations"].items():
            allocated[lid] = allocated.get(lid, 0) + qty
    out = {p: 0 for p in data["products"]}
    for lot in data["lots"]:
        if not lot.get("optional"):
            out[lot["product"]] += lot["quantity"] - allocated.get(lot["id"], 0)
    return out


def pull_ahead_cap(data):
    """Per product: how many units reserve work may make ahead of time, or None.

    Contract-manufacturing policy (A08): reserve production is "làm trước" for
    confirmed long-term orders beyond the horizon, never speculative stock. So
    chosen reserve lots + reserve BTP runs of product p may not exceed p's
    long-term demand minus what mandatory lots already over-produce for p.
    None = dataset declares no long_term_orders (reserve bounded only by
    max_surplus / inventory_cap, the pre-policy behaviour).
    """
    if "long_term_orders" not in data:
        return None
    demand = {p: 0 for p in data["products"]}
    for order in data["long_term_orders"]:
        demand[order["product"]] += order["quantity"]
    tech = technical_surplus(data)
    return {p: max(0, demand[p] - tech[p]) for p in data["products"]}


def stage_items(data, stage):
    """Every code a machine at `stage` may legitimately be keyed by.

    BTP stage: any catalogued BTP code not routed at a DIFFERENT stage (a code
    no product routes to yet is allowed, so re-routing a product never strands a
    machine). qc: finished products.
    """
    if stage in BTP_STAGES:
        elsewhere = {codes[s] for codes in data["btp_routing"].values() for s in BTP_STAGES if s != stage}
        return set(data.get("btp_codes", [])) - elsewhere
    return set(data["products"])


def _check_routing(data):
    """A09 routing must give every stage an unambiguous input.

    Input of stage k = output of stage k-1, so two products that share a code at
    stage k must share the code at every earlier stage (routes may only split
    going downstream, never merge); otherwise one F_CNC run would not know which
    cast pool to draw from. A code also belongs to exactly one stage.
    """
    routing = data["btp_routing"]
    owner = {}
    for p in data["products"]:
        assert all(s in routing.get(p, {}) for s in BTP_STAGES), f"Missing BTP routing for '{p}'"
    for p, codes in routing.items():
        for s in BTP_STAGES:
            prior = owner.setdefault(codes[s], s)
            assert prior == s, f"BTP code '{codes[s]}' used at both '{prior}' and '{s}'"
    assert not set(owner) & set(data["products"]), "BTP codes must differ from finished product codes"
    products = list(routing)
    for i, p in enumerate(products):
        for q in products[i+1:]:
            for k, s in enumerate(BTP_STAGES):
                if routing[p][s] == routing[q][s]:
                    for earlier in BTP_STAGES[:k]:
                        assert routing[p][earlier] == routing[q][earlier], (
                            f"'{p}' and '{q}' share '{routing[p][s]}' at {s} but differ at {earlier}: "
                            f"ambiguous input for {s}")


def _check_machine_keys(data):
    """schema_version 4: machine data keyed by stage item, never by final product at a BTP stage."""
    for mid, spec in data["machines"].items():
        valid = stage_items(data, spec["stage"])
        rates = set(spec["minutes_per_unit"])
        assert rates <= valid, (f"{mid}: minutes_per_unit keys {sorted(rates - valid)} are not "
                                f"{spec['stage']}-stage items {sorted(valid)}")
        states = {spec["initial_product"]}
        if "mold" in spec:
            states.add(spec["mold"]["after_maintenance"])
        # A row is either one of this machine's items or a pure machine state
        # (INITIAL, CLEAN, ...); a product/BTP code from another stage is a keying error.
        codes = set(data["products"]) | set(data.get("btp_codes", []))
        for prev, row in spec["setup"].items():
            assert prev in valid or prev not in codes, f"{mid}: setup row '{prev}' is not a {spec['stage']} item"
            assert set(row) <= valid, f"{mid}: setup row '{prev}' has non-{spec['stage']} items {sorted(set(row) - valid)}"
            assert rates <= set(row), f"{mid}: setup row '{prev}' misses {sorted(rates - set(row))}"
        for state in states:
            assert state in spec["setup"], f"{mid}: missing setup row for state '{state}'"


def check_input(data):
    """Reject inputs outside the explicit experimental contract before solving."""
    lots = {l["id"]: l for l in data["lots"]}
    assert len(lots) == len(data["lots"]), "Duplicate lot ids"
    assert len({o["id"] for o in data["orders"]}) == len(data["orders"]), "Duplicate order ids"
    assert data["stages"] == list(STAGES)
    assert data.get("schema_version") == 4, "schema_version 4 required: machine data keyed by stage item"
    _check_routing(data)
    _check_machine_keys(data)
    allocated = {lid:0 for lid in lots}
    initial = {p:0 for p in data["products"]}
    molds = []
    for machine in data["machines"].values():
        windows = sorted(machine["windows"],key=lambda w:w["start"])
        assert all(0 <= w["start"] < w["end"] <= data["horizon"] for w in windows)
        assert all(a["end"] <= b["start"] for a,b in zip(windows,windows[1:])), "Overlapping calendar"
        for shift in machine["shifts"]:
            assert shift["available_minutes"] == sum(w["end"]-w["start"] for w in windows if w["shift"] == shift["id"])
        if "mold" in machine:
            mold = machine["mold"]
            molds.append(mold["id"])
            assert 0 <= mold["initial_cycles"] <= mold["limit_cycles"]
            assert mold["cavities"] > 0 and mold["maintenance_minutes"] > 0
    assert len(molds) == len(set(molds)), "This experiment requires dedicated, non-shared molds"
    for lot in lots.values():
        assert lot["quantity"] >= data["minimum_lot"] and lot["release"] >= 0
        assert len(eligible(data,lot,"cast")) == 1, "One dedicated casting machine per family required"
        mold = data["machines"][eligible(data,lot,"cast")[0]]["mold"]
        assert math.ceil(lot["quantity"]/mold["cavities"]) <= mold["limit_cycles"]
        assert all(eligible(data,lot,s) for s in STAGES), "Missing eligible machine"
    for order in data["orders"]:
        assert order["quantity"] > 0 and order["priority"] > 0
        assert order["initial_allocated"] >= 0 and order["lot_allocations"]
        initial[order["product"]] += order["initial_allocated"]
        assert sum(order["lot_allocations"].values())+order["initial_allocated"] == order["quantity"]
        for lid,qty in order["lot_allocations"].items():
            assert lid in lots and qty > 0 and lots[lid]["product"] == order["product"]
            assert lots[lid]["order"] == order["id"], "Decoder assumes one parent order per fixed lot"
            assert lots[lid]["release"] >= order["release"]
            allocated[lid] += qty
    # A08/4.3.2: an optional (reserve) lot is never tied to an order's
    # lot_allocations by construction -- it exists to fill idle capacity /
    # safety stock, not a specific order -- so it is exempt from the
    # "every lot backs some order" rule that mandatory lots must satisfy.
    assert all(l.get("optional") or (0 < allocated[lid] <= l["quantity"]) for lid,l in lots.items())
    assert all(initial[p] <= data["initial_inventory"][p] for p in initial)
    # Static part of A02/R04: technical surplus of MANDATORY lots is fixed by the
    # input. Reserve lots only count once chosen, so the solver/validator enforce
    # technical + chosen reserve <= max_surplus (an unchosen candidate costs nothing).
    assert sum(technical_surplus(data).values()) <= data["max_surplus"], "Technical surplus exceeds max_surplus"
    long_term_ids = [o["id"] for o in data.get("long_term_orders", [])]
    assert len(set(long_term_ids)) == len(long_term_ids), "Duplicate long_term_orders ids"
    assert not set(long_term_ids) & {o["id"] for o in data["orders"]}, "long_term_orders id collides with an order"
    for order in data.get("long_term_orders", []):
        assert order["product"] in data["products"], f"long_term_orders '{order['id']}': unknown product"
        assert order["quantity"] > 0, f"long_term_orders '{order['id']}': quantity must be positive"
        # Beyond this run's horizon by definition; in-horizon demand belongs in `orders`.
        assert order["due"] > data["horizon"], f"long_term_orders '{order['id']}': due must be after the horizon"
    assert data.get("transfer_minutes", 0) >= 0, "transfer_minutes must be non-negative"
    # BTP (semi-finished) catalog + routing (A09): a btp_code is a free-standing
    # identity, distinct from finished product codes, that one or more
    # (product, stage in {cast,cnc,paint}) routings can share.
    btp_codes_list = data.get("btp_codes", [])
    assert len(set(btp_codes_list)) == len(btp_codes_list), "Duplicate BTP codes"
    btp_codes = set(btp_codes_list)
    btp_routing = data.get("btp_routing", {})
    for p in data["products"]:
        assert p in data.get("product_color", {}), f"Missing catalog color for product '{p}'"
        assert p in data.get("product_line", {}), f"Missing catalog line for product '{p}'"
        for s in BTP_STAGES:
            code = btp_routing.get(p, {}).get(s)
            assert code is not None, f"Missing BTP routing for ({p}, {s})"
            assert code in btp_codes, f"BTP routing ({p}, {s}) references unknown code '{code}'"
    inventory_btp = data.get("inventory_btp", {})
    btp_capacity = data.get("btp_capacity", {})
    for code, qty in inventory_btp.items():
        assert code in btp_codes, f"inventory_btp references unknown BTP code '{code}'"
        assert qty >= 0
    for code, cap in btp_capacity.items():
        assert code in btp_codes, f"btp_capacity references unknown BTP code '{code}'"
        assert cap > 0
    # Every lot runs every stage (mandatory-lot model); a given lot's own stage-k
    # production always resolves to the SAME code as its own stage-(k+1)
    # consumption (both via btp_routing[lot.product][stage_k]), so no schedule can
    # create BTP surplus beyond declared initial stock, even when products share a
    # code — summing per-code (not per-product) avoids double counting shared codes.
    assert sum(inventory_btp.values()) <= data.get("max_surplus_btp", 0)
    # R04: optional per-product cap on finished-goods inventory ("trần tồn theo
    # sản phẩm"). Absent = uncapped (unchanged pre-A08 behaviour).
    inventory_cap = data.get("inventory_cap", {})
    for p, cap in inventory_cap.items():
        assert p in data["products"], f"inventory_cap references unknown product '{p}'"
        assert cap > 0 and cap >= data["initial_inventory"][p], f"inventory_cap for '{p}' below opening stock"
    # A08/4.3.2-4.3.3: optional (reserve) work generated up front as a finite set
    # of candidates -- the solver only gets a chosen/not-chosen decision per
    # candidate, it never invents lot sizes or run counts itself (mục 3.2 keeps
    # joint lot-size optimisation out of scope).
    for run in data.get("optional_btp_runs", []):
        assert run["id"] not in lots, f"optional_btp_runs id '{run['id']}' collides with a lot id"
        assert run["product"] in data["products"], f"optional_btp_runs references unknown product '{run['product']}'"
        assert run["stage"] in BTP_STAGES, f"optional_btp_runs stage must be one of {BTP_STAGES}"
        assert run["quantity"] >= data["minimum_lot"] and run["release"] >= 0
        assert eligible(data, run, run["stage"]), f"optional_btp_runs '{run['id']}': missing eligible machine"
        if run["stage"] == "cast":
            assert len(eligible(data, run, "cast")) == 1, "One dedicated casting machine per family required"
            mold = data["machines"][eligible(data, run, "cast")[0]]["mold"]
            assert math.ceil(run["quantity"]/mold["cavities"]) <= mold["limit_cycles"], \
                f"optional_btp_runs '{run['id']}': exceeds mold cycle limit"
    run_ids = [r["id"] for r in data.get("optional_btp_runs", [])]
    assert len(set(run_ids)) == len(run_ids), "Duplicate optional_btp_runs ids"
    policy = data.get("reserve_policy")
    if policy is not None:
        for p in policy.get("finished_products", []):
            assert p in data["products"], f"reserve_policy.finished_products: unknown product '{p}'"
        for p, stages in policy.get("btp_products", {}).items():
            assert p in data["products"], f"reserve_policy.btp_products: unknown product '{p}'"
            assert all(s in BTP_STAGES for s in stages), f"reserve_policy.btp_products['{p}']: bad stage"
        for mid, shift_keys in policy.get("closable_shifts", {}).items():
            assert mid in data["machines"], f"reserve_policy.closable_shifts: unknown machine '{mid}'"
        assert policy.get("finished_lot_size", data["minimum_lot"]) >= data["minimum_lot"]
        assert policy.get("btp_run_size", data["minimum_lot"]) >= data["minimum_lot"]
    for machine in data["machines"].values():
        closable_ids = {s["id"] for s in machine["shifts"] if s.get("closable")}
        for window in machine["windows"]:
            if window.get("closable"):
                assert window["shift"] in closable_ids, "closable window must belong to a closable shift"


def build(seed=20260919):
    rng = random.Random(seed)
    products = ["F_SILVER", "F_BLACK", "R_SILVER", "R_BLACK"]
    # Wall-clock minutes from 00:00 Monday 2026-09-21; weekend retained.
    days = [0, 1, 2, 3, 4, 7, 8, 9, 10, 11]
    specs = {
        "CAST_F": ("cast", products[:2], 1.05, 5),
        "CAST_R": ("cast", products[2:], 1.2, 5),
        "CNC_1": ("cnc", products[:3], 1.65, 8),
        "CNC_2": ("cnc", products, 1.85, 8),
        "PAINT_1": ("paint", products, .70, 30),
        "PAINT_2": ("paint", products, .85, 30),
        "QC_1": ("qc", products, .65, 8),
    }
    machines = {}
    for mid, (stage, allowed, rate, fixed) in specs.items():
        matrix = {}
        for prev in products + ["CLEAN"]:
            matrix[prev] = {}
            for product in products:
                if prev == product:
                    val = 0
                elif stage == "paint":
                    val = 12 if prev.endswith("SILVER") and product.endswith("BLACK") else 24
                    if prev != "CLEAN" and prev.split("_")[1] == product.split("_")[1]:
                        val = 0
                else:
                    val = {"cast": 12, "cnc": 18, "qc": 4}[stage]
                    if prev == "CLEAN":
                        val += 4
                matrix[prev][product] = val
        downtime = []
        if mid == "CNC_1":
            downtime = [[2 * 1440 + 840, 2 * 1440 + 1020]]
        if mid == "PAINT_1":
            downtime = [[7 * 1440 + 360, 7 * 1440 + 600]]
        windows, shifts = [], []
        for day in days:
            for shift_num, (a, b, c, d) in enumerate([(360, 600, 630, 840), (840, 1080, 1110, 1320)]):
                sid = f"D{day+1:02}_S{shift_num+1}"
                segments = [[day * 1440 + a, day * 1440 + b], [day * 1440 + c, day * 1440 + d]]
                for lo, hi in downtime:
                    pieces = []
                    for x, y in segments:
                        if hi <= x or lo >= y:
                            pieces.append([x, y])
                        else:
                            if x < lo:
                                pieces.append([x, lo])
                            if hi < y:
                                pieces.append([hi, y])
                    segments = pieces
                shifts.append({"id": sid, "day": day, "start": day * 1440 + a,
                               "end": day * 1440 + d, "available_minutes": sum(y-x for x,y in segments)})
                for x, y in segments:
                    windows.append({"id": len(windows), "shift": sid, "start": x, "end": y})
        # schema_version 4: key by stage item. Every product has its own code at every
        # stage here (no sharing), so this is a pure relabel of the product-keyed formula.
        item = lambda x: f"{x}_{stage.upper()}" if stage in BTP_STAGES and x in products else x
        matrix = {item(prev): {item(p): v for p, v in row.items()} for prev, row in matrix.items()}
        machines[mid] = {"stage": stage, "minutes_per_unit": {item(p): rate for p in allowed},
                         "fixed_minutes": fixed, "initial_product": item(allowed[0]), "setup": matrix,
                         "windows": windows, "shifts": shifts, "downtime": downtime}
        if stage == "cast":
            machines[mid]["mold"] = {"id": f"MOLD_{mid[-1]}", "cavities": 2,
                                       "limit_cycles": 140, "initial_cycles": 95 if mid == "CAST_F" else 115,
                                       "maintenance_minutes": 45, "after_maintenance": "CLEAN"}
    orders, lots = [], []
    first = set()
    for i in range(36):
        product = products[(i * 3 + i // 4) % 4]
        wave = i // 6
        release_day = days[wave]
        release = release_day * 1440 + 360
        urgent = i in [7, 16, 25, 31]
        due_day = days[min(9, wave + (0 if urgent else rng.choice([1, 1, 2, 2])))]
        due = due_day * 1440 + (840 if urgent else 1320)
        initial = 12 if product not in first else 0
        first.add(product)
        count = 2 if i % 3 == 0 else 1
        order_lots = []
        allocated = []
        for k in range(count):
            qty = rng.choice([60, 72, 84, 96])
            lid = f"L{len(lots)+1:03}"
            order_lots.append(lid)
            allocated.append(qty - (4 if k == count - 1 else 0))
            lots.append({"id": lid, "order": f"O{i+1:03}", "product": product,
                         "quantity": qty, "release": release})
        orders.append({"id": f"O{i+1:03}", "product": product, "release": release, "due": due,
                       "priority": 4 if urgent else rng.choice([1, 1, 2]), "urgent": urgent,
                       "quantity": sum(allocated) + initial, "initial_allocated": initial,
                       "lot_allocations": dict(zip(order_lots, allocated))})
    data = {"schema_version": 4, "name": "wheel_factory_48_lots_2weeks", "seed": seed,
            "origin": "2026-09-21T00:00:00+07:00", "time_unit": "minute", "horizon": 14 * 1440,
            "working_days": days, "stages": list(STAGES), "products": products,
            "product_color": {p: p.split("_")[1] for p in products},
            "product_line": {p: p.split("_")[0] for p in products},
            "initial_inventory": {p: 18 for p in products}, "safety_stock": {p: 30 for p in products},
            "btp_codes": [f"{p}_{s.upper()}" for p in products for s in BTP_STAGES],
            "btp_routing": {p: {s: f"{p}_{s.upper()}" for s in BTP_STAGES} for p in products},
            "inventory_btp": {}, "btp_capacity": {}, "max_surplus_btp": 0, "transfer_minutes": 10,
            "checkpoints": [(d+1)*1440 for d in range(14)], "minimum_lot": 60,
            "max_surplus": 144, "machines": machines, "orders": orders, "lots": lots,
            "weights": {"makespan": 1, "weighted_tardiness": 15, "setup_minutes": 3,
                        "idle_minutes": 1, "safety_shortfall": 20},
            "assumptions": [
                "Synthetic engineering assumptions, not measured factory data.",
                "Fixed lots and fixed order allocation; no partial shipment; ship as soon as all allocated lots finish QC.",
                "Dedicated fixed front/rear molds; finish variants share geometry. No mold transport.",
                "Maintenance is mandatory just before the next lot would exceed cycles; no discretionary early maintenance.",
                "Maintenance + setup + processing form one contiguous block inside an availability window for ALL methods.",
                "Block cannot cross a break or shift boundary; conservative restriction beyond the general requirements.",
                "Shifts are activated iff occupied. Setup, maintenance and processing all count as occupied time.",
                "Urgent releases and downtime known at planning time; this is an offline comparison, not online rescheduling.",
                "No WIP at origin; material available at release; no scrap or labor capacity.",
                "Fixed 10-minute transfer lag between adjacent stages (cast->cnc->paint->qc) before "
                "BTP is available downstream; no explicit transportation resource/routing modeled."]}
    return data


if __name__ == "__main__":
    save_json(DEFAULT_INPUT, build())
    print(DEFAULT_INPUT)

common/search.py:
from __future__ import annotations

import math
import random
import time
from .decoder import decode
from .evaluate import evaluate
from .instance import STAGES, eligible


def initial_genome(data):
    # A08: optional lots are never dispatched by decode() (it pre-marks them
    # done, see decoder.py) so their priority never actually matters here --
    # they simply have no order to rank by. Sort them last with a neutral key
    # instead of touching `orders[...]`, which would KeyError on `lot["order"]`.
    orders = {o["id"]:o for o in data["orders"]}
    def key(i):
        lot = data["lots"][i]
        if lot.get("optional"):
            return (float("inf"), 0, i)
        return (orders[lot["order"]]["due"], -orders[lot["order"]]["priority"], i)
    order = sorted(range(len(data["lots"])), key=key)
    rank = {idx:r for r,idx in enumerate(order)}
    return [float(rank[i]*4+k) for i in range(len(order)) for k in range(4)]


def optimize(data, method, seconds, seed):
    rng = random.Random(seed)
    started = time.perf_counter()
    n = len(data["lots"])*4
    def decode_genome(genome):
        priorities, genes = genome[:n],genome[n:]
        bias = {}
        j = 0
        for i,lot in enumerate(data["lots"]):
            for k,stage in enumerate(STAGES):
                for mid in eligible(data,lot,stage):
                    bias[i,k,mid] = genes[j]
                    j += 1
        return decode(data, priorities=priorities, machine_bias=bias)
    extra = sum(len(eligible(data,l,s)) for l in data["lots"] for s in STAGES)
    first = initial_genome(data)+[0.0]*extra
    evaluated, history = 0, []
    best, best_score = None, float("inf")
    def assess(g):
        nonlocal evaluated,best,best_score
        rows = decode_genome(g)
        evaluated += 1
        score = evaluate(data,rows)[0]["objective"] if rows else float("inf")
        if score < best_score:
            best,best_score = rows,score
            history.append({"seconds":time.perf_counter()-started,"objective":score,"evaluations":evaluated})
        return score
    def mutate(g):
        x = g.copy()
        for _ in range(rng.choice([1,2,4])):
            if rng.random() < .7:
                a,b = rng.sample(range(n),2)
                x[a],x[b] = x[b],x[a]
            else:
                a = rng.randrange(n,len(x))
                x[a] = rng.uniform(-600,600)
        return x
    score = assess(first)
    if method == "sa":
        current = first
        steps,accepted = 0,0
        while time.perf_counter()-started < seconds:
            candidate = mutate(current)
            value = assess(candidate)
            fraction = min(1,(time.perf_counter()-started)/seconds)
            temperature = max(1,score*.04*(.005**fraction))
            if value < score or (math.isfinite(value) and rng.random() < math.exp(min(0,(score-value)/temperature))):
                current,score = candidate,value
                accepted += 1
            steps += 1
        details = {"iterations":steps,"accepted_moves":accepted,"initial_temperature_fraction":.04}
    else:
        population = [(score,first)]
        while len(population) < 14 and time.perf_counter()-started < seconds:
            g = first.copy()
            for _ in range(8):
                g = mutate(g)
            population.append((assess(g),g))
        generations = 0
        while time.perf_counter()-started < seconds:
            population.sort(key=lambda t:t[0])
            new = population[:2]
            while len(new) < len(population) and time.perf_counter()-started < seconds:
                def tournament():
                    return min(rng.sample(population,min(3,len(population))),key=lambda t:t[0])[1]
                a,b = tournament(),tournament()
                child = [x if rng.random()<.5 else y for x,y in zip(a,b)]
                child = mutate(child)
                new.append((assess(child),child))
            population = new
            generations += 1
        details = {"generations":generations,"population_size":14,"elite":2,"selection":"tournament_3","crossover":"uniform_random_keys"}
    return best,{"status":"HEURISTIC_FEASIBLE" if best else "NO_SOLUTION_FOUND", "history":history,
                 "evaluations":evaluated,"bound":None,**details}

common/stage_runs/decoder.py:
"""Serial schedule generation for schema 5 (FIFO/EDD/SPT and the SA/GA decoder).

Same mechanism as the schema-4 decoder (models/common/decoder.py): at each step
every ready mandatory run gets its earliest feasible placement (append-only per
machine, first window it fits in); the run with the earliest block start wins,
ties broken by the rule key. Reserve options are never chosen here -- that is an
economic decision, not a dispatch rule (same as schema 4). A QC lot also waits
while the finished-goods warehouse would exceed stock_cap at a checkpoint.

Speed (same output as the plain version, checked in tests): a run's best placement
only changes when something it depends on changes -- the state of a machine it can
use, of a mold it can use, the stock of the code it consumes, or the finished lots
of its product. Placing a run marks exactly the runs that depend on what it
changed; only those are recomputed, every other cached placement is reused. The first
window that can hold a block is found by binary search on window ends.
"""
from __future__ import annotations

from bisect import bisect_left, insort

from .instance import (calendar, cast_setup, cycles, duration, eligible, molds_for, quantity,
                       run_due, upstream, btp_stages)


def _ready_time(initial, credits, consumed, qty):
    """Earliest time cumulative stock covers everything already consumed plus qty
    (safe for consumers placed earlier or later, see validate()). `credits` is kept
    sorted by the caller."""
    need = consumed + qty
    available = initial
    if available >= need:
        return 0
    for t, q in credits:
        available += q
        if available >= need:
            return t
    return None


def _cap_ready(data, product, lots, qty, out=None):
    """Earliest block start for a QC lot of `qty` so finished stock stays within
    stock_cap at every checkpoint: a full warehouse makes packing wait. Deliveries
    are projected at their release (the pickup time), lots already placed at their
    end. Returns 0 when no checkpoint is at risk, or when even the last one is
    (then nothing helps -- validate() reports it)."""
    spec = data["products"][product]
    if out is None:
        out = [(o["release"], o["quantity"]) for o in data["orders"] if o["product"] == product]
    late = [c for c in data["checkpoints"]
            if spec["initial_stock"] + sum(q for t, q in lots if t <= c) - sum(q for t, q in out if t <= c) + qty > spec["stock_cap"]]
    if not late or late[-1] == data["checkpoints"][-1]:
        return 0
    return late[-1]


def decode(data, rule="edd", priorities=None, machine_bias=None, delays=None, options=()):
    """delays: {run index: minutes} -- the run may not start before its earliest
    feasible time plus this delay (lets a search wait to consolidate shifts).
    options: reserve options to include (all their runs); rules pass none."""
    runs = data["runs"]
    todo = [i for i, r in enumerate(runs) if r.get("reserve_option") in (None, *options)]
    due = run_due(data)
    up = upstream(data)
    windows = {m: calendar(data, m)[0] for m in data["machines"]}
    ends = {m: [w["end"] for w in ws] for m, ws in windows.items()}
    mach = {m: {"end": 0, "item": data["machine_initial_state"], "mold": None} for m in data["machines"]}
    molds = {k: {"used": v["initial_cycles"], "free": 0} for k, v in data.get("molds", {}).items()}
    credits = {c: [] for c in data["btp"]}
    consumed = {c: 0 for c in data["btp"]}
    finished = {p: [] for p in data["products"]}
    shipped = {p: [(o["release"], o["quantity"]) for o in data["orders"] if o["product"] == p] for p in data["products"]}
    btp = set(btp_stages(data))

    static = {}  # per run: quantity, consumed code, (machine, mold, minutes, cycles) options, due
    for i in todo:
        run = runs[i]
        opts = [(mid, mold, duration(data, run, mid), cycles(data, run, mold) if mold else 0)
                for mid in eligible(data, run) for mold in (molds_for(data, run["item"]) or [None])]
        static[i] = (quantity(data, run), up[run["item"]], opts, due[run["id"]])

    # who depends on what: placing a run dirties exactly these runs' cached placement
    by_mach, by_mold, by_code, by_prod = {}, {}, {}, {}
    for i, (_, code, opts, _) in static.items():
        for mid, mold, _, _ in opts:
            by_mach.setdefault(mid, set()).add(i)
            if mold:
                by_mold.setdefault(mold, set()).add(i)
        if code:
            by_code.setdefault(code, set()).add(i)
        if runs[i]["item"] in finished:
            by_prod.setdefault(runs[i]["item"], set()).add(i)
    cache = {}
    dirty = set(todo)

    def place(i):
        run = runs[i]
        q, code, opts, _ = static[i]
        lower = 0
        if code:
            lower = _ready_time(data["btp"][code]["initial_stock"], credits[code], consumed[code], q)
            if lower is None:
                return None
        if run["item"] in finished:
            lower = max(lower, _cap_ready(data, run["item"], finished[run["item"]], q, shipped[run["item"]]))
        if delays:
            lower += delays.get(i, 0)
        best = None
        for mid, mold, p, c in opts:
            st = mach[mid]
            maint, used, free = 0, 0, 0
            if mold:
                spec = data["molds"][mold]
                used, free = molds[mold]["used"] + c, molds[mold]["free"]
                if used > spec["limit_cycles"]:
                    maint, used = spec["maintenance_minutes"], c
            su = cast_setup(data, mid, st["item"], st["mold"], run["item"], mold, maint > 0)
            earliest = max(st["end"], lower, free)
            length = maint + su + p
            ws = windows[mid]
            # windows ending before earliest + length cannot hold the block: skip them
            for k in range(bisect_left(ends[mid], earliest + length), len(ws)):
                w = ws[k]
                b = max(earliest, w["start"])
                if b + length <= w["end"]:
                    row = {"run": run["id"], "stage": run["stage"], "item": run["item"], "machine": mid,
                           "block_start": b, "start": b + maint + su, "end": b + length,
                           "setup_minutes": su, "maintenance_minutes": maint, "mold": mold,
                           "cycles_after": used if mold else 0, "window": w["id"], "shift": w["shift"]}
                    bias = 0 if machine_bias is None else machine_bias.get((i, mid), 0)
                    key = (row["end"] + bias, row["end"], mid, mold or "")
                    if best is None or key < best[0]:
                        best = (key, row)
                    break
        return None if best is None else best[1]

    rows = []
    while todo:
        candidates = []
        for i in dirty:
            cache[i] = place(i)
        dirty.clear()
        for i in todo:
            row = cache[i]
            if row is None:
                continue
            d, prio = static[i][3]
            if priorities is not None:
                key = (priorities[i], i)
            elif rule == "fifo":
                key = (0, i)  # every run is released at 0: input order
            elif rule == "spt":
                key = (row["end"] - row["start"], d, i)
            else:
                key = (d, -prio, i)
            candidates.append(((row["block_start"], key), i, row))
        if not candidates:
            return None
        _, i, row = min(candidates, key=lambda c: c[0])
        run = runs[i]
        rows.append(row)
        mach[row["machine"]] = {"end": row["end"], "item": run["item"], "mold": row["mold"]}
        dirty |= by_mach[row["machine"]]
        if row["mold"]:
            molds[row["mold"]] = {"used": row["cycles_after"], "free": row["end"]}
            dirty |= by_mold[row["mold"]]
        q = static[i][0]
        if run["stage"] in btp:
            insort(credits[run["item"]], (row["end"] + data["transfer_minutes"][run["stage"]], q))
            dirty |= by_code.get(run["item"], set())
        if up[run["item"]]:
            consumed[up[run["item"]]] += q
            dirty |= by_code.get(up[run["item"]], set())
        if run["item"] in finished:
            finished[run["item"]].append((row["end"], q))
            dirty |= by_prod[run["item"]]
        todo.remove(i)
        cache.pop(i, None)
        dirty &= set(todo)
    return rows

common/stage_runs/evaluate.py:
"""Independent validator + KPI evaluator for schema-5 schedules.

Row: {"run","stage","item","machine","block_start","start","end","setup_minutes",
      "maintenance_minutes","mold","cycles_after","window","shift"}.
validate() rebuilds everything from the input and the timestamps; it never trusts
a solver's flags. evaluate() uses the same objective terms as the schema-4 engine
(models/common/evaluate.py) so results stay comparable.
"""
from __future__ import annotations

from collections import Counter
from .instance import (btp_stages, calendar, cast_setup, cycles, duration, eligible, last_stage,
                       order_of_lot, quantity, reserve_groups, upstream, uses_molds)


def option_quantity(data, option):
    """Units an option pulls ahead: its QC lot, or (BTP-only option) its runs."""
    runs = {r["id"]: r for r in data["runs"]}
    ids = reserve_groups(data)[option]
    lots = [i for i in ids if runs[i]["stage"] == last_stage(data)]
    return sum(quantity(data, runs[i]) for i in (lots or ids))


def chosen_options(data, rows):
    present = {r["run"] for r in rows}
    return sorted(o for o, ids in reserve_groups(data).items() if all(i in present for i in ids))


def _deliveries(data, rows):
    qc = {r["run"]: r["end"] for r in rows if r["stage"] == last_stage(data)}
    out = []
    for o in data["orders"]:
        t = max([o["release"]] + [qc.get(l, float("inf")) for l in o["lot_allocations"]])
        out.append({"order": o["id"], "product": o["product"], "time": t, "quantity": o["quantity"],
                    "due": o["due"], "tardiness": max(0, t - o["due"]), "priority": o["priority"]})
    return out


def _finished_events(data, rows, deliveries):
    runs = {r["id"]: r for r in data["runs"]}
    ev = [(r["end"], 0, runs[r["run"]]["item"], quantity(data, runs[r["run"]]), r["run"])
          for r in rows if r["stage"] == last_stage(data)]
    ev += [(d["time"], 1, d["product"], -d["quantity"], d["order"]) for d in deliveries]
    return sorted(ev)


def validate(data, rows):
    errors = []
    runs = {r["id"]: r for r in data["runs"]}
    counts = Counter(r["run"] for r in rows)
    unknown = [i for i in counts if i not in runs]
    if unknown or any(v != 1 for v in counts.values()):
        return {"valid": False, "errors": [f"unknown or duplicated runs: {sorted(unknown) or [i for i, v in counts.items() if v != 1]}"]}
    mandatory = {r["id"] for r in data["runs"] if "reserve_option" not in r}
    missing = mandatory - set(counts)
    if missing:
        errors.append(f"missing mandatory runs: {sorted(missing)}")
    for option, ids in reserve_groups(data).items():
        got = [i for i in ids if i in counts]
        if got and len(got) != len(ids):
            errors.append(f"reserve option {option}: runs {sorted(set(ids) - set(got))} missing (all-or-nothing)")
    cal = {m: calendar(data, m) for m in data["machines"]}
    for r in rows:
        run, p = runs[r["run"]], f'{r["run"]}'
        if any(not isinstance(r[k], int) or isinstance(r[k], bool) for k in
               ("block_start", "start", "end", "setup_minutes", "maintenance_minutes", "cycles_after")):
            errors.append(p + ": times and minutes must be whole minutes (int)")
            continue
        if r["stage"] != run["stage"] or r.get("item") != run["item"]:
            errors.append(p + ": stage/item differ from input")
        if r["machine"] not in eligible(data, run):
            errors.append(p + f": {r['machine']} cannot make {run['item']}")
            continue
        if r["end"] - r["start"] != duration(data, run, r["machine"]):
            errors.append(p + ": wrong duration")
        if r["block_start"] + r["maintenance_minutes"] + r["setup_minutes"] != r["start"]:
            errors.append(p + ": block pieces do not add up")
        wins = [w for w in cal[r["machine"]][0] if w["id"] == r["window"]]
        if not wins or wins[0]["shift"] != r["shift"] or not (wins[0]["start"] <= r["block_start"] and r["end"] <= wins[0]["end"]):
            errors.append(p + ": outside its calendar window")
        if not 0 <= r["block_start"] < r["end"] <= data["horizon"]:
            errors.append(p + ": outside horizon")
        if uses_molds(data, run):
            if r["mold"] not in data["molds"] or data["molds"][r["mold"]]["item"] != run["item"]:
                errors.append(p + ": needs a mold for " + run["item"])
        elif r["mold"] is not None or r["maintenance_minutes"]:
            errors.append(p + ": mold/maintenance on a stage without molds")
    # molds: one machine at a time, cycle counter, maintenance exactly when needed
    for k, spec in data.get("molds", {}).items():
        used, last_end = spec["initial_cycles"], None
        for r in sorted((r for r in rows if r["mold"] == k), key=lambda r: r["block_start"]):
            if last_end is not None and r["block_start"] < last_end:
                errors.append(f"{k}: used by two runs at once ({r['run']})")
            c = cycles(data, runs[r["run"]], k)
            need = used + c > spec["limit_cycles"]
            if need != bool(r["maintenance_minutes"]) or (need and r["maintenance_minutes"] != spec["maintenance_minutes"]):
                errors.append(f"{r['run']}: maintenance of {k} {'missing' if need else 'not allowed'}")
            used = (0 if need else used) + c
            if r["cycles_after"] != used:
                errors.append(f"{r['run']}: wrong cycle counter for {k}")
            last_end = r["end"]
    # machines: no overlap, setup from predecessor (item, mold, maintenance)
    for mid, spec in data["machines"].items():
        prev_item, prev_mold, last_end = data["machine_initial_state"], None, 0
        for r in sorted((r for r in rows if r["machine"] == mid), key=lambda r: r["block_start"]):
            if r["block_start"] < last_end:
                errors.append(f"{mid}: overlap at {r['run']}")
            item = runs[r["run"]]["item"]
            want = cast_setup(data, mid, prev_item, prev_mold, item, r["mold"], r["maintenance_minutes"] > 0)
            if r["setup_minutes"] != want:
                errors.append(f"{r['run']}: setup {r['setup_minutes']} != {want}")
            prev_item, prev_mold, last_end = item, r["mold"], r["end"]
    # BTP stock (A09/A10/R12): credit at end + transfer of the producing stage,
    # debit at the consuming block start; credit first at the same minute.
    up = upstream(data)
    events = []
    for r in rows:
        run = runs[r["run"]]
        if run["stage"] in btp_stages(data):
            events.append((r["end"] + data["transfer_minutes"][run["stage"]], 0, run["item"], quantity(data, run)))
        if up[run["item"]]:
            events.append((r["block_start"], 1, up[run["item"]], -quantity(data, run)))
    level = {c: v["initial_stock"] for c, v in data["btp"].items()}
    for t, _, code, q in sorted(events):
        level[code] = level.get(code, 0) + q
        if level[code] < 0:
            errors.append(f"BTP {code} negative at t={t}")
        cap = data["btp"].get(code, {}).get("capacity")
        if cap is not None and level[code] > cap:
            errors.append(f"BTP {code} above capacity at t={t}")
    deliveries = _deliveries(data, rows)
    inv = {p: s["initial_stock"] for p, s in data["products"].items()}
    for t, _, p, q, src in _finished_events(data, rows, deliveries):
        inv[p] += q
        if inv[p] < 0:
            errors.append(f"{p}: negative finished stock at t={t} ({src})")
    for c in data["checkpoints"]:
        for p, v in _stock_at(data, rows, deliveries, c).items():
            if v > data["products"][p]["stock_cap"]:
                errors.append(f"{p}: above stock_cap at checkpoint {c}")
    return {"valid": not errors, "errors": errors, "operations_checked": len(rows),
            "scope": "schema 5: fixed runs per stage, shared mold pool, one window per block"}


def _stock_at(data, rows, deliveries, checkpoint):
    values = {p: s["initial_stock"] for p, s in data["products"].items()}
    for t, _, p, q, _src in _finished_events(data, rows, deliveries):
        if t <= checkpoint:
            values[p] += q
    return values


def evaluate(data, rows):
    runs = {r["id"]: r for r in data["runs"]}
    deliveries = _deliveries(data, rows)
    shifts = []
    for mid in data["machines"]:
        for sh in calendar(data, mid)[1]:
            mine = [r for r in rows if r["machine"] == mid and r["shift"] == sh["id"]]
            if not mine:
                continue
            processing = sum(r["end"] - r["start"] for r in mine)
            setup = sum(r["setup_minutes"] for r in mine)
            maint = sum(r["maintenance_minutes"] for r in mine)
            shifts.append({"machine": mid, "shift": sh["id"], "available": sh["available_minutes"],
                           "processing": processing, "setup": setup, "maintenance": maint,
                           "idle": sh["available_minutes"] - processing - setup - maint,
                           "utilization": processing / sh["available_minutes"]})
    daily = []
    for c in data["checkpoints"]:
        for p, v in _stock_at(data, rows, deliveries, c).items():
            safe = data["products"][p]["safety_stock"]
            daily.append({"time": c, "product": p, "inventory": v, "shortfall": max(0, safe - v), "surplus": max(0, v - safe)})
    options = chosen_options(data, rows)
    lots = [r for r in rows if r["stage"] == last_stage(data)]
    mandatory_lots = [r for r in lots if "reserve_option" not in runs[r["run"]]]
    available = sum(s["available"] for s in shifts)
    processing = sum(s["processing"] for s in shifts)
    ledger = []
    inv = {p: s["initial_stock"] for p, s in data["products"].items()}
    for t, k, p, q, src in _finished_events(data, rows, deliveries):
        inv[p] += q
        ledger.append({"time": t, "kind": "QC" if k == 0 else "SHIP", "source": src, "product": p, "delta": q, "inventory": inv[p]})
    up = upstream(data)
    btp_end = {c: v["initial_stock"] for c, v in data["btp"].items()}
    for r in rows:
        run = runs[r["run"]]
        if run["stage"] in btp_stages(data):
            btp_end[run["item"]] = btp_end.get(run["item"], 0) + quantity(data, run)
        if up[run["item"]]:
            btp_end[up[run["item"]]] -= quantity(data, run)
    metrics = {
        "makespan": max((r["end"] for r in mandatory_lots), default=0),
        "mandatory_makespan": max((r["end"] for r in mandatory_lots), default=0),
        "schedule_end": max(r["end"] for r in rows),
        "weighted_tardiness": sum(d["priority"] * d["tardiness"] for d in deliveries),
        "total_tardiness": sum(d["tardiness"] for d in deliveries),
        "late_orders": sum(d["tardiness"] > 0 for d in deliveries),
        "max_tardiness": max((d["tardiness"] for d in deliveries), default=0),
        "setup_minutes": sum(r["setup_minutes"] for r in rows),
        "maintenance_minutes": sum(r["maintenance_minutes"] for r in rows),
        "maintenance_count": sum(r["maintenance_minutes"] > 0 for r in rows),
        "idle_minutes": sum(s["idle"] for s in shifts),
        "safety_shortfall": sum(d["shortfall"] for d in daily),
        "activated_shifts": len(shifts),
        "productive_utilization": processing / available if available else None,
        "processing_minutes": processing, "available_minutes": available,
        "produced_quantity": sum(quantity(data, runs[r["run"]]) for r in lots),
        "shipped_quantity": sum(d["quantity"] for d in deliveries),
        "end_inventory": inv, "btp_end": btp_end,
        "reserve_production": len(options),
        "reserve_quantity": sum(option_quantity(data, o) for o in options),
        "surplus_holding": sum(d["surplus"] for d in daily),
        "shift_opening": 0,
        "reserve_options_chosen": options,
        # Every minute of an opened (staffed) shift is paid; only processing makes
        # product. Setup and maintenance are therefore non-productive here and carry
        # their own extra weight in the objective -- never a discount (see SOURCE.md).
        "nonproductive_minutes": available - processing,
        "reserve_units": sum(option_quantity(data, o) for o in options),
        "btp_end_units": sum(btp_end.values()),
    }
    metrics.update(objective_terms(data, metrics))
    return metrics, {"deliveries": deliveries, "inventory_events": ledger, "daily_inventory": daily, "shifts": shifts}


def objective_terms(data, metrics):
    """Lexicographic objective (requirements mục 4.3.2): tier 1 = service level
    (tardiness, safety shortfall) strictly before tier 2 = operating cost.
    objective = scale * tier1 + tier2, with scale larger than any tier-2 value."""
    tiers = data.get("objective_tiers", {})
    first = set(tiers.get("tier1", []))
    scale = tiers.get("scale", 1)
    t1 = sum(w * metrics[k] for k, w in data["weights"].items() if k in first)
    t2 = sum(w * metrics[k] for k, w in data["weights"].items() if k not in first)
    return {"objective_tier1": t1, "objective_tier2": t2, "objective": scale * t1 + t2}

common/stage_runs/experiment.py:
"""Method dispatch for schema 5 -- mirrors models/common/experiment.execute().

Called from models.common.experiment.execute() when the input has
schema_version 5, so every run_one/run_all artifact path stays the same.
"""
from __future__ import annotations

import os
import random
import time
from .compact import compact
from .decoder import decode
from .evaluate import evaluate, validate
from .instance import canonical


def heuristic_start(data, seconds=6.0):
    """Best dispatch-rule schedule after shift consolidation -- the incumbent/hint
    for CP-SAT+hint and CP-LNS. Returns (rows, objective, rule)."""
    best = (None, float("inf"), None)
    for rule in ("fifo", "edd", "spt"):
        rows = decode(data, rule)
        if rows is None:
            continue
        rows = compact(data, rows, seconds=seconds / 3)
        if not validate(data, rows)["valid"]:
            continue
        value = evaluate(data, rows)[0]["objective"]
        if value < best[1]:
            best = (canonical(data, rows), value, rule)
    return best


def _neighbourhood(data, incumbent, rng, kind):
    ids = [r["id"] for r in data["runs"]]
    if kind == "time":  # everything touching a random 8-16 h window: lets whole shifts empty out
        start = rng.randrange(0, data["horizon"] - 480, 60)
        length = rng.choice([480, 720, 960])
        return {r["run"] for r in incumbent if r["block_start"] < start + length and r["end"] > start}
    if kind == "machine":
        machines = rng.sample(list(data["machines"]), 2)
        return {r["run"] for r in incumbent if r["machine"] in machines}
    if kind == "stage":
        stage = rng.choice(data["stages"])
        return {r["id"] for r in data["runs"] if r["stage"] == stage}
    return set(rng.sample(ids, max(4, len(ids) // 5)))


def execute(data, method, seconds, seed, workers=None):
    """workers: CP-SAT search workers; default MNFT_CP_WORKERS or 1 (fair single-thread comparison).
    MNFT_PATIENCE (seconds): SA/GA/CP-LNS stop after this long without improvement;
    `seconds` then acts as a safety cap. Unset = run the whole budget (default)."""
    started = time.perf_counter()
    workers = workers or int(os.environ.get("MNFT_CP_WORKERS", "1"))
    patience = float(os.environ["MNFT_PATIENCE"]) if os.environ.get("MNFT_PATIENCE") else None
    if method in ("fifo", "edd", "spt"):
        rows = decode(data, rule=method)
        return rows, {"status": "HEURISTIC_FEASIBLE" if rows else "NO_SOLUTION_FOUND", "bound": None, "history": []}
    if method in ("simulated_annealing", "genetic_algorithm"):
        from .search import optimize
        return optimize(data, "sa" if method == "simulated_annealing" else "ga", seconds, seed, patience)
    if method == "cp_rolling":
        from .rolling import solve_rolling
        return solve_rolling(data, seconds=seconds, seed=seed, workers=workers)
    from .cp_engine import solve
    if method == "cp_sat":
        rows, meta = solve(data, seconds=seconds, seed=seed, workers=workers)
        meta["workers"] = workers
        return rows, meta
    incumbent, initial, rule = heuristic_start(data)
    if incumbent is None:
        return None, {"status": "NO_SOLUTION_FOUND", "history": [], "bound": None}
    source = f"{rule.upper()} + dồn ca"
    if method == "cp_sat_hint":
        rows, meta = solve(data, seconds=max(.01, seconds - (time.perf_counter() - started)), seed=seed,
                           hint=incumbent, workers=workers)
        meta["solver_status"] = meta["status"]
        meta["initial_hint_objective"] = initial
        meta["hint_source"] = source
        meta["workers"] = workers
        if rows is None or evaluate(data, rows)[0]["objective"] > initial:
            rows = incumbent
            meta["status"] = "HEURISTIC_FALLBACK"
            meta.pop("solver_objective", None)
        meta["history"].insert(0, {"seconds": time.perf_counter() - started, "objective": initial, "source": source})
        return rows, meta
    if method != "cp_lns":
        raise ValueError(f"unknown method {method}")
    rng = random.Random(seed)
    best = initial
    history = [{"seconds": time.perf_counter() - started, "objective": best, "source": source}]
    iterations = []
    kinds = ["time", "machine", "stage", "random"]
    last_gain = time.perf_counter() - started
    stop = "budget"
    while seconds - (time.perf_counter() - started) > 3:
        if patience is not None and time.perf_counter() - started - last_gain >= patience:
            stop = "no_improvement"
            break
        kind = kinds[len(iterations) % len(kinds)]
        released = _neighbourhood(data, incumbent, rng, kind)
        fixed = {r["run"] for r in incumbent} - released
        rows, meta = solve(data, seconds=min(10, seconds - (time.perf_counter() - started)),
                           seed=seed + len(iterations), hint=incumbent, fixed_runs=fixed, workers=workers)
        iterations.append({"neighbourhood": kind, "released_runs": sorted(released), "status": meta["status"],
                           "build_seconds": meta["build_seconds"], "solve_seconds": meta["solve_seconds"]})
        if rows:
            check = validate(data, rows)
            if not check["valid"]:
                raise ValueError(check)
            value = evaluate(data, rows)[0]["objective"]
            if abs(value - meta["solver_objective"]) > .01:
                raise ValueError("LNS objective disagrees with independent evaluator")
            if value < best:
                incumbent, best = canonical(data, rows), value
                last_gain = time.perf_counter() - started
                history.append({"seconds": time.perf_counter() - started, "objective": value,
                                "iteration": len(iterations), "neighbourhood": kind})
    return incumbent, {"status": "HEURISTIC_FEASIBLE", "history": history, "iterations": iterations, "bound": None,
                       "bound_scope": "none; neighborhood bounds are not global", "initial_hint_objective": initial,
                       "hint_source": source, "workers": workers, "patience_seconds": patience, "stop_reason": stop}

common/stage_runs/instance.py:
"""Schema-5 input: helpers shared by the evaluator, decoder and CP model.

Conventions fixed here (and documented in dataset/wheel-factory-small/SOURCE.md):
  * A run's quantity is run_size[stage]; its duration on machine m is
    ceil(quantity * minutes_per_unit + fixed_minutes).
  * Calendar: a machine with calendar "continuous" works the whole horizon; any
    other machine works every shift of shift_template each day. A run block
    (maintenance + setup + processing) lies inside ONE window = one shift minus
    its breaks and the machine's downtime (same rule as the schema-4 engine).
  * Molds are a pool keyed by the item they cast; a cast run uses exactly one
    mold of its item. Mounting a different mold than the machine's previous run
    costs at least mold_change_minutes; after maintenance the setup row is the
    mold's after_maintenance state.
"""
from __future__ import annotations

import math


class InputError(ValueError):
    pass


def btp_stages(data):
    return data["stages"][:-1]


def last_stage(data):
    return data["stages"][-1]


def upstream(data):
    """Item -> the item its stage consumes (None for the first stage)."""
    out = {}
    stages = btp_stages(data)
    for product, spec in data["products"].items():
        chain = [spec["route"][s] for s in stages] + [product]
        for k, item in enumerate(chain):
            out[item] = chain[k - 1] if k else None
    return out


def quantity(data, run):
    return data["run_size"][run["stage"]]


def duration(data, run, machine):
    spec = data["machines"][machine]
    return math.ceil(quantity(data, run) * spec["minutes_per_unit"][run["item"]] + spec["fixed_minutes"])


def eligible(data, run):
    return [m for m, spec in data["machines"].items()
            if spec["stage"] == run["stage"] and run["item"] in spec["minutes_per_unit"]]


def molds_for(data, item):
    return [k for k, spec in data.get("molds", {}).items() if spec["item"] == item]


def uses_molds(data, run):
    return bool(molds_for(data, run["item"]))


def cycles(data, run, mold):
    return math.ceil(quantity(data, run) / data["molds"][mold]["cavities"])


def is_continuous(data, machine):
    return data["machines"][machine].get("calendar") == "continuous"


def _cut(spans, holes):
    for a0, a1 in holes:
        spans = [p for s, e in spans for p in ((s, min(e, a0)), (max(s, a1), e)) if p[1] > p[0]]
    return spans


def calendar(data, machine):
    """(windows, shifts) of one machine.

    windows: [{"id", "shift", "start", "end"}], shifts: [{"id", "start", "end", "available_minutes"}].
    A continuous machine has windows with shift None and no shifts (it never
    enters the idle-minutes KPI: nobody is rostered to it).
    """
    spec = data["machines"][machine]
    downtime = [tuple(d) for d in spec.get("downtime", [])]
    windows, shifts = [], []
    if spec.get("calendar") == "continuous":
        for s, e in _cut([(0, data["horizon"])], downtime):
            windows.append({"id": len(windows), "shift": None, "start": s, "end": e})
        return windows, shifts
    for day in range(data["horizon"] // 1440):
        for key, sh in data["shift_template"].items():
            start, end = day * 1440 + sh["start"], day * 1440 + sh["end"]
            breaks = [(day * 1440 + a, day * 1440 + b) for a, b in sh.get("breaks", [])]
            spans = _cut(_cut([(start, end)], breaks), downtime)
            sid = f"D{day + 1:02}_{key}"
            shifts.append({"id": sid, "start": start, "end": end, "available_minutes": sum(e - s for s, e in spans)})
            for s, e in spans:
                windows.append({"id": len(windows), "shift": sid, "start": s, "end": e})
    return windows, shifts


def cast_setup(data, machine, prev_item, prev_mold, item, mold, maintained):
    """Setup before a run on `machine` (see module docstring for the mold rules)."""
    spec = data["machines"][machine]
    if maintained:
        return spec["setup"][data["molds"][mold]["after_maintenance"]][item]
    base = spec["setup"][prev_item][item]
    if mold is not None and prev_mold is not None and mold != prev_mold:
        return max(base, spec.get("mold_change_minutes", 0))
    return base


def reserve_groups(data):
    groups = {}
    for run in data["runs"]:
        if "reserve_option" in run:
            groups.setdefault(run["reserve_option"], []).append(run["id"])
    return groups


def order_of_lot(data):
    out = {}
    for order in data["orders"]:
        for lot in order["lot_allocations"]:
            out[lot] = order
    return out


def run_due(data):
    """Dispatch due date / priority per run: a QC lot takes its order's; an upstream
    run takes the most urgent order whose product route passes through its item.
    Reserve-only runs get no order (infinite due)."""
    lot_order = order_of_lot(data)
    out = {}
    for run in data["runs"]:
        if run["id"] in lot_order:
            o = lot_order[run["id"]]
            out[run["id"]] = (o["due"], o["priority"])
            continue
        prods = [p for p, s in data["products"].items()
                 if run["item"] == p or run["item"] in s["route"].values()]
        orders = [o for o in data["orders"] if o["product"] in prods]
        out[run["id"]] = (min(o["due"] for o in orders), max(o["priority"] for o in orders)) if orders and "reserve_option" not in run else (math.inf, 0)
    return out


def check(data):
    """Reject a schema-5 input the engine cannot interpret unambiguously."""
    def need(cond, msg):
        if not cond:
            raise InputError(msg)
    need(data.get("schema_version") == 5, "stage_runs engine needs schema_version 5")
    stages = data["stages"]
    need(set(data["run_size"]) == set(stages), "run_size must give one size per stage")
    need(set(data["transfer_minutes"]) == set(btp_stages(data)), "transfer_minutes must cover every stage but the last")
    ids = [r["id"] for r in data["runs"]]
    need(len(ids) == len(set(ids)), "duplicate run id")
    up = upstream(data)
    for run in data["runs"]:
        need(run["stage"] in stages, f"{run['id']}: unknown stage")
        need(eligible(data, run), f"{run['id']}: no machine makes {run['item']}")
        need(run["item"] in up, f"{run['id']}: item {run['item']} not on any product route")
        if uses_molds(data, run):
            for k in molds_for(data, run["item"]):
                need(cycles(data, run, k) <= data["molds"][k]["limit_cycles"], f"{run['id']}: run exceeds {k} cycle limit")
    for mid, spec in data["machines"].items():
        need(data["machine_initial_state"] in spec["setup"], f"{mid}: no setup row for initial state")
        need(spec.get("calendar", "shifts") in ("shifts", "continuous"), f"{mid}: bad calendar")
        for item in spec["minutes_per_unit"]:
            for row in spec["setup"].values():
                need(item in row, f"{mid}: setup matrix misses {item}")
    for k, mold in data.get("molds", {}).items():
        for mid, spec in data["machines"].items():
            if mold["item"] in spec["minutes_per_unit"]:
                need(mold["after_maintenance"] in spec["setup"], f"{mid}: no setup row after maintenance of {k}")
    lots = {r["id"]: r for r in data["runs"] if r["stage"] == last_stage(data)}
    for o in data["orders"]:
        need(sum(o["lot_allocations"].values()) + o["initial_allocated"] == o["quantity"], f"{o['id']}: allocation")
        for lid, q in o["lot_allocations"].items():
            need(lid in lots and lots[lid]["item"] == o["product"] and "reserve_option" not in lots[lid], f"{o['id']}: bad lot {lid}")
            need(0 < q <= data["run_size"][last_stage(data)], f"{o['id']}: bad quantity for {lid}")
    for code in data["btp"]:
        need(code in up, f"btp {code} not on any route")
    groups = reserve_groups(data)
    need(set(groups) == set(data.get("reserve_options", {})), "reserve_options and runs disagree")
    known = {"makespan", "weighted_tardiness", "setup_minutes", "maintenance_minutes", "nonproductive_minutes",
             "idle_minutes", "safety_shortfall", "reserve_units", "reserve_production", "surplus_holding", "btp_end_units"}
    need(set(data["weights"]) <= known, f"unknown weight keys {sorted(set(data['weights']) - known)}")
    tiers = data.get("objective_tiers", {})
    need(set(tiers.get("tier1", [])) <= set(data["weights"]), "objective_tiers.tier1 must name weighted terms")
    return data


def twin_groups(data):
    """Mandatory runs that are fully interchangeable: same stage and item and, for
    QC lots, the same order and allocated quantity. Returned in declaration order."""
    lot_order = {lid: (o["id"], q) for o in data["orders"] for lid, q in o["lot_allocations"].items()}
    groups = {}
    for run in data["runs"]:
        if "reserve_option" in run:
            continue
        groups.setdefault((run["stage"], run["item"], lot_order.get(run["id"])), []).append(run["id"])
    return [ids for ids in groups.values() if len(ids) > 1]


def canonical_map(data, rows):
    """{old run id: new run id} that orders interchangeable twins by block start."""
    by_run = {r["run"]: r for r in rows}
    relabel = {}
    for ids in twin_groups(data):
        present = [i for i in ids if i in by_run]
        ordered = sorted(present, key=lambda i: (by_run[i]["block_start"], ids.index(i)))
        for new_id, old_id in zip(present, ordered):
            relabel[old_id] = new_id
    return relabel


def canonical(data, rows):
    """Relabel interchangeable runs so their ids follow block-start order. The
    schedule is unchanged (twins are identical); it just agrees with the solver's
    symmetry-breaking order, so it can be used as a hint or fixed neighbourhood."""
    relabel = canonical_map(data, rows)
    return [{**r, "run": relabel.get(r["run"], r["run"])} for r in rows]

